        super.onCreate(savedInstanceState)
        enableEdgeToEdge()
        // Comprobación de token para login automático o no
        val authRepository: AuthRepository = AuthRepositoryImpl()
        val startDestination = if (authRepository.getCurrentUserUid() != null) {
            "listaCinturones"
