    // Lógica del Dialog de Solicitar Examen
    if (showSolicitarExamenDialog) {
        SolicitarExamenDialog(
            onConfirm = {
                showSolicitarExamenDialog = false
                viewModel.requestExam()
            },
            onDismiss = { showSolicitarExamenDialog = false }
        )
    }
    // Para botón atrás del móvil
    val context = LocalContext.current as? Activity

    // Interceptamos el botón de atrás
    BackHandler {
        // Cerramos la aplicación por completo
        context?.finish()
    }
    LazyColumn(
        modifier = Modifier
            .fillMaxSize()
            .padding(paddingValues),
        contentPadding = PaddingValues(bottom = 20.dp)
    ) {
        // --- CARD DATOS PERFIL ---
        item {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(start = 12.dp, end = 12.dp, top = 16.dp, bottom = 16.dp),
                shape = RoundedCornerShape(24.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
            ) {
                Column(
                    modifier = Modifier.padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text(text = "Datos perfil", style = MaterialTheme.typography.titleMedium)

                    // AVATAR
                    Surface(
                        modifier = Modifier.size(100.dp),
                        shape = CircleShape,
                        color = MaterialTheme.colorScheme.onSecondary
                    ) {
                        Box(contentAlignment = Alignment.Center) {
                            Text(
                                text = if (nombre.isNotEmpty()) nombre.take(1).uppercase() else "?",
                                style = MaterialTheme.typography.displayMedium,
                                fontWeight = FontWeight.Bold,
                                color = MaterialTheme.colorScheme.primary
                            )
                        }
                    }

                    CampoPerfil(label = "Nombre", value = nombre, onValueChange = { nombre = it })
                    CampoPerfil(
                        label = "Apellidos",
                        value = apellidos,
                        onValueChange = { apellidos = it })
                    CampoPerfil(
                        label = "Teléfono",
                        value = telefono,
                        onValueChange = { telefono = it })
                    CampoPerfil(label = "Email", value = email, onValueChange = {}, enabled = false)

                    Spacer(modifier = Modifier.height(8.dp))

                    // BOTÓN ACTUALIZAR
                    Button(
                        onClick = { showConfirmDialog = true },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(55.dp),
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(containerColor = Color(0xFF2D0C03))
                    ) {
                        Text("Actualizar", fontWeight = FontWeight.Bold, fontSize = 18.sp)
                    }
                }
            }
        }
        // --- CARD SOLICITAR EXAMEN ---
        item {
            Card(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(
                        start = 12.dp,
                        end = 12.dp,
                        bottom = 16.dp
                    ), // Margen inferior para separarlo de Cerrar Sesión
                shape = RoundedCornerShape(24.dp),
                colors = CardDefaults.cardColors(containerColor = MaterialTheme.colorScheme.surface),
                elevation = CardDefaults.cardElevation(defaultElevation = 8.dp)
            ) {
                Column(
                    modifier = Modifier
                        .fillMaxWidth()
                        .padding(20.dp),
                    horizontalAlignment = Alignment.CenterHorizontally,
                    verticalArrangement = Arrangement.spacedBy(16.dp)
                ) {
                    Text(
                        text = "Solicitar examen",
                        style = MaterialTheme.typography.titleMedium,
                    )

                    // Lógica para el mensaje informativo
                    val mensajeInformativo = when {
                        examStatus == "APPROVED" -> "¡Enhorabuena! Has aprobado tu último examen."
                        examStatus == "FAILED" -> "No has superado el examen. Sigue practicando."
                        examStatus == "APPLICANT" -> "Esperando aprobación de solicitud..."
                        examStatus == "REFUSED" -> "Tu solicitud de examen ha sido rechazada."
                        examStatus == "CANDIDATE" && estadoExamenGlobal == "IN_PROGRESS" -> "¡Tu examen está en curso! Suerte."
                        estadoExamenGlobal == "OPEN_REQUESTS" && examStatus == "NONE" -> "¡Ya puedes solicitar tu examen!"
                        else -> "No hay proceso de examen en estos momentos."
                    }

                    // Card interior o recuadro para resaltar el mensaje del profesor
                    Surface(
                        modifier = Modifier.fillMaxWidth(),
                        shape = RoundedCornerShape(12.dp),
                        color = MaterialTheme.colorScheme.onSecondary
                    ) {
                        Column(
                            modifier = Modifier.padding(16.dp),
                            horizontalAlignment = Alignment.CenterHorizontally
                        ) {
                            Text(
                                text = mensajeInformativo,
                                textAlign = TextAlign.Center
                            )
                            if (examText.isNotBlank()) {
                                Spacer(modifier = Modifier.height(8.dp))
                                Text(
                                    text = examText,
                                    textAlign = TextAlign.Center,
                                )
                            }
                        }
                    }

                    // Botón para acceder
                    val botonHabilitado =
                        estadoExamenGlobal == "OPEN_REQUESTS" && examStatus == "NONE"

                    Button(
                        onClick = { showSolicitarExamenDialog = true },
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(55.dp),
                        enabled = botonHabilitado,
                        shape = RoundedCornerShape(12.dp),
                        colors = ButtonDefaults.buttonColors(
                            disabledContainerColor = Color.LightGray
                        )
                    ) {
                        Text(
                            text = "Acceder al examen",
                            fontWeight = if (botonHabilitado) FontWeight.Bold else FontWeight.Normal,
                            fontSize = 18.sp,
                            color = if (botonHabilitado) MaterialTheme.colorScheme.onPrimary else MaterialTheme.colorScheme.primary
                        )
                    }
                }
            }
        }
        // --- 2. SECCIÓN DE CERRAR SESIÓN ---
        item {
            Spacer(modifier = Modifier.height(16.dp))
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = 16.dp),
                horizontalArrangement = Arrangement.Center,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Icon(
                    imageVector = Icons.AutoMirrored.Filled.Logout,
                    contentDescription = "Salir",
                    modifier = Modifier
                        .size(20.dp)
                        .clickable { }
                )
                Spacer(
                    modifier = Modifier
                        .width(8.dp)
                )
                Text(
                    modifier = Modifier.clickable { showLogoutDialog = true },
                    text = "Cerrar sesión",
                    fontWeight = FontWeight.Bold,
                    textAlign = TextAlign.Center
                )
            }
        }
    }
}

